define(['editor_tiny/loader'], function(TinyMCE) {
    return {
        init: function() {
            TinyMCE.PluginManager.add('fontcase', function(editor) {

                // Helper function to change case of selected text cleanly
                var changeCase = function(toCase) {
                    var selectedText = editor.selection.getContent({format: 'text'});
                    if (selectedText.length > 0) {
                        var newText = toCase === 'upper' ? selectedText.toUpperCase() : selectedText.toLowerCase();
                        editor.insertContent(newText);
                    }
                };

                // 1. Register a clear toolbar button with visible text labeling
                editor.ui.registry.addButton('fontcase', {
                    text: 'Aa', // Simple, recognizable text label instead of a missing icon
                    tooltip: 'Change Case',
                    onAction: function() {
                        // Toggles selection to UPPERCASE by default on a single click
                        changeCase('upper');
                    }
                });

                // 2. Register child menu items
                editor.ui.registry.addMenuItem('fontcase_upper', {
                    text: 'UPPERCASE',
                    onAction: function() {
 changeCase('upper');
}
                });

                editor.ui.registry.addMenuItem('fontcase_lower', {
                    text: 'lowercase',
                    onAction: function() {
 changeCase('lower');
}
                });

                // 3. Nest items into a clean drop-down menu element for the menubar
                editor.ui.registry.addNestedMenuItem('fontcase_menu', {
                    text: 'Font Case',
                    getSubmenuItems: function() {
                        return ['fontcase_upper', 'fontcase_lower'];
                    }
                });
            });
        }
    };
});
